SELECT cs.canonical_smiles, m.substrate_record_id, m.metabolite_record_id, rsubstrate.compound_key AS substrate_compound_key, rmetabolite.compound_key AS metabolite_compound_key, m.met_conversion, m.pathway_key FROM metabolism m INNER JOIN compound_records rsubstrate ON rsubstrate.record_id = m.substrate_record_id INNER JOIN compound_structures cs ON cs.molregno = rsubstrate.molregno LEFT JOIN compound_records rmetabolite ON rmetabolite.record_id = m.metabolite_record_id ORDER BY cs.canonical_smiles, m.substrate_record_id, m.metabolite_record_id, rsubstrate.compound_key, rmetabolite.compound_key, m.met_conversion, m.pathway_key LIMIT 200
